/**
 * The most recent reading a series holds strictly before an instant, however
 * long before it was published. A provisioned dimension keeps the level it was
 * last set to, so a window that opens after the last reading still has to be
 * told what the standing level is.
 *
 * The reply is asked for newest first, so the first page already carries the
 * reading we are after and there is no need to walk the whole history.
 */
export const readLatestUsageSampleBefore = async ({
    series,
    before,
}: {
    series: UsageSeries;
    before: Date;
}): Promise<UsageSample | undefined> => {
    try {
        const cloudwatchClient = usageClient();
        const response = await cloudwatchClient.send(
            new GetMetricDataCommand({
                StartTime: new Date(0),
                EndTime: before,
                ScanBy: 'TimestampDescending',
                MetricDataQueries: [
                    {
                        Id: 'usage',
                        MetricStat: {
                            Metric: {
                                Namespace: USAGE_NAMESPACE,
                                MetricName: USAGE_METRIC_NAME,
                                Dimensions: Object.keys(series).map((Name) => ({
                                    Name,
                                    Value: series[Name],
                                })),
                            },
                            Period: SAMPLE_PERIOD_SECONDS,
                            Stat: 'Maximum',
                        },
                        ReturnData: true,
                    },
                ],
            }),
        );
        let latest: UsageSample;
        (response?.MetricDataResults ?? []).forEach(({ Timestamps, Values }) => {
            (Timestamps ?? []).forEach((timestamp, index) => {
                const sample = { timestamp: new Date(timestamp).toISOString(), value: Number(Values?.[index]) };
                if (!latest || sample.timestamp > latest.timestamp) {
                    latest = sample;
                }
            });
        });
        return latest;
    } catch (err) {
        return failed(err);
    }
};
