import { aggregationInterval } from '../dimensions/dto/create-dimension.dto.js';

/** One step of a usage curve, inclusive of its start and exclusive of its end. */
export type UsageStep = { startTime: string; endTime: string };

/** The clock edge a step of the given size starts on, at or before the instant. */
const edgeAtOrBefore = (date: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.hour:
            return new Date(
                Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate(), date.getUTCHours()),
            );
        case aggregationInterval.day:
            return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
        case aggregationInterval.month:
            return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1));
        default:
            return new Date(date.getTime());
    }
};

/** The clock edge the step after the one starting on the given edge starts on. */
const nextEdge = (edge: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.hour:
            return new Date(
                Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate(), edge.getUTCHours() + 1),
            );
        case aggregationInterval.day:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate() + 1));
        case aggregationInterval.month:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth() + 1, 1));
        default:
            return undefined;
    }
};

/**
 * The steps a window is reported in for a given step size. Edges sit on the
 * clock, so an hourly curve breaks on the hour, a daily one at midnight UTC and
 * a monthly one on the first of the month. The first and the last step are
 * clamped to the window, so neither reaches outside of what was asked for.
 */
export const usageStepsBetween = ({
    startTime,
    endTime,
    interval,
}: {
    startTime: string | Date;
    endTime: string | Date;
    interval: aggregationInterval;
}): UsageStep[] => {
    const windowStart = new Date(startTime);
    const windowEnd = new Date(endTime);
    if (!(windowStart.getTime() < windowEnd.getTime())) {
        return [];
    }
    if (!interval || interval === aggregationInterval.none) {
        return [{ startTime: windowStart.toISOString(), endTime: windowEnd.toISOString() }];
    }

    const steps: UsageStep[] = [];
    let edge = edgeAtOrBefore(windowStart, interval);
    while (edge.getTime() < windowEnd.getTime()) {
        const following = nextEdge(edge, interval);
        const stepStart = edge.getTime() > windowStart.getTime() ? edge : windowStart;
        const stepEnd = following.getTime() < windowEnd.getTime() ? following : windowEnd;
        steps.push({ startTime: stepStart.toISOString(), endTime: stepEnd.toISOString() });
        edge = following;
    }
    return steps;
};
