const pricedByMetadataGroup = ({ tiersGroupByMetadata }: ReadDimensionResponseData): boolean =>
    Array.isArray(tiersGroupByMetadata) && tiersGroupByMetadata.length > 0;

/** Readings arrive in whatever order the metric store hands them over. */
const oldestFirst = (samples: UsageSample[]): UsageSample[] =>
    [...samples].sort((left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime());

/** Numbers travel as strings, without the noise floating point arithmetic adds. */
const usageValueOf = (value: number): string => `${Number(value.toFixed(10))}`;

/** The metadata a series was published under, or nothing when it carries none. */
const metadataGroupOf = (series: UsageSeries): Record<string, string> | undefined => {
    const metadata = metadataOf(series);
    return Object.keys(metadata).length ? metadata : undefined;
};

/** A stable order for the groups of one dimension, the plain series first. */
const byMetadataGroup = (left: UsageSeries, right: UsageSeries): number =>
    JSON.stringify(metadataOf(left)).localeCompare(JSON.stringify(metadataOf(right)));

/** One curve: the value of every step of the window, in order. */
const curveOfReadings = ({
    samples,
    steps,
    method,
    holdLevel,
    standingLevel,
    metadataGroup,
}: {
    samples: UsageSample[];
    steps: UsageStep[];
    method: aggregationMethod;
    holdLevel: boolean;
    standingLevel?: number;
    metadataGroup?: Record<string, string>;
}): UsageResponseDocument[] => {
    const readings = oldestFirst(samples).map(({ timestamp, value }) => ({
        at: new Date(timestamp).getTime(),
        value,
    }));
    // A level set before the window opened is still the level the window opens on.
    let carried = holdLevel ? standingLevel : undefined;
    return steps.map(({ startTime, endTime }) => {
        const opens = new Date(startTime).getTime();
        const closes = new Date(endTime).getTime();
        const inStep = readings.filter(({ at }) => at >= opens && at < closes).map(({ value }) => value);
        let value: number;
        if (inStep.length) {
            value = reduceSamples(inStep, method);
            carried = value;
        } else {
            value = carried === undefined ? 0 : carried;
        }
        return new UsageDocument({ value: usageValueOf(value), startTime, endTime, metadataGroup });
    });
};

/** What one published series holds for a window, and the level it opens on. */
const readSeriesForWindow = async ({
    series,
    startTime,
    endTime,
    holdLevel,
}: {
    series: UsageSeries;
    startTime: string;
    endTime: string;
    holdLevel: boolean;
}): Promise<{ samples: UsageSample[]; standingLevel?: UsageSample }> => {
    const samples = await readUsageSamples({
        series,
        startTime: new Date(startTime),
        endTime: new Date(endTime),
    });
    const standingLevel = holdLevel
        ? await readLatestUsageSampleBefore({ series, before: new Date(startTime) })
        : undefined;
    return { samples, standingLevel };
};

/** One dimension's answer: a curve, or one curve for each published group. */
type DimensionUsageCurve = {
    usage: UsageResponseDocument[] | BasicUsageDocument[];
    metadataGroup?: Record<string, string>;
};
"""

