    public aggregationPurpose?: AggregationPurpose;

    private static dimensionFunctionMap = {
        [usageData]: async ({
            businessID,
            startTime,
            endTime,
            dimension,
            customerId,
        }: SingleUsageEvent): Promise<DimensionUsageCurve[]> => {
            const {
                dimensionId,
                aggregationInterval: argumentAgg,
                aggregationMethod: argumentAggregationMethod,
            } = dimension as ReadDimensionResponseData;
            const published = await listUsageSeries({ businessID, customerId, dimensionId });
            // A customer with no readings still has a curve, it is just an empty one,
            // so the plain series stands in for a dimension nothing was published to.
            const series = published.length
                ? [...published].sort(byMetadataGroup)
                : [usageSeriesOf({ businessID, customerId, dimensionId })];

            if (argumentAgg !== aggregationInterval.none) {
                const steps = usageStepsBetween({ startTime, endTime, interval: argumentAgg });
                const holdLevel = holdsItsLevel(dimension as ReadDimensionResponseData);
                const read = [];
                for (const seriesOfGroup of series) {
                    read.push({
                        series: seriesOfGroup,
                        ...(await readSeriesForWindow({
                            series: seriesOfGroup,
                            startTime,
                            endTime,
                            holdLevel,
                        })),
                    });
                }

                if (pricedByMetadataGroup(dimension as ReadDimensionResponseData)) {
                    // Every group is priced on its own, so every group is reported on its own.
                    return read.map(({ series: seriesOfGroup, samples, standingLevel }) => ({
                        metadataGroup: metadataGroupOf(seriesOfGroup),
                        usage: curveOfReadings({
                            samples,
                            steps,
                            method: argumentAggregationMethod,
                            holdLevel,
                            standingLevel: standingLevel?.value,
                            metadataGroup: metadataGroupOf(seriesOfGroup),
                        }),
                    }));
                }

                // Otherwise whatever the readings were published under is one dimension.
                const samples = read.reduce((acc, { samples }) => acc.concat(samples), [] as UsageSample[]);
                const standingLevel = read
                    .map(({ standingLevel }) => standingLevel)
                    .filter((sample) => sample !== undefined)
                    .sort((left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime())
                    .pop();
                return [
                    {
                        usage: curveOfReadings({
                            samples,
                            steps,
                            method: argumentAggregationMethod,
                            holdLevel,
                            standingLevel: standingLevel?.value,
                        }),
                    },
                ];
            }

            const unAggregatedResults: BasicUsageDocument[] = [];
            for (const seriesOfGroup of published) {
                const samples = await readUsageSamples({
                    series: seriesOfGroup,
                    startTime: new Date(startTime),
                    endTime: new Date(endTime),
                });
                const metadata = metadataOf(seriesOfGroup);
                oldestFirst(samples).forEach(({ timestamp, value }) => {
                    unAggregatedResults.push({ timestamp, recordValue: value.toString(), metadata });
                });
            }
            return [
                {
                    usage: unAggregatedResults.sort(
                        (left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime(),
                    ),
                },
            ];
        },
    };

    static buildAggregationQueries = async ({
        offeringDocument,
        ...rest
    }: UsageAggregationEvent): Promise<
        Array<UnAggregatedUsageResponse | AggregatedUsageResponse | MetadataGroupedAggregatedUsageResponse[]>
    > => {
        const results = await Promise.all(
            offeringDocument.dimensions.map(async ({ dimensionId, ...dimensionRest }) => {
                const curves = await UsageAggregationEvent.dimensionFunctionMap['usageData']({
                    dimension: { ...dimensionRest, dimensionId },
                    ...rest,
                });
                return curves.map(({ usage, metadataGroup }) => ({
                    offeringId: offeringDocument?.offeringId,
                    dimensionId,
                    ...(metadataGroup ? { metadataGroup } : {}),
                    usage,
                }));
            }),
        );
        return results as unknown as Array<UnAggregatedUsageResponse | AggregatedUsageResponse>;
    };
"
}

